-- What supabase/designers.sql does, tried inside the rolled-back transaction
-- of a dry run: nothing here is kept.
--
--   set -a; . ./.env; set +a
--   PG_MODULE=/tmp/pg/node_modules/pg/lib/index.js \
--     node tools/apply_sql.mjs supabase/designers.sql --dry --try=tools/designers_try.sql --table=model_opens
--
-- After the live files (trust, tested, comments, builds, versions, follows,
-- discovery), which the project has. Made-up accounts, made and gone with
-- the transaction: Ada designs (13 or over, a profile), Bob builds and
-- remixes her models (13 or over, a profile), Ed builds one too (13 or
-- over, no profile), Cy says he is under 13 after making a
-- profile. Every model a test model, so no visitor's answer has them. Times are
-- set by hand: inside one transaction now() never moves. Each statement is
-- on one line: the dry run splits at a semicolon that ends a line.
-- First, before anything here is counted: the opens already in model_views counted in once: every (model, day) it has is in model_opens, at least as many.
select count(*) as "days in model_views not in model_opens" from (select v.model, v.day, count(*) as n from public.model_views v group by v.model, v.day) v left join public.model_opens o on o.model = v.model and o.day = v.day where o.opens is null or o.opens < v.n;
-- How long it takes on the real tables, before anything is made here: the busiest designer with a profile, their page and their own numbers; and the owner with the most models.
create function pg_temp.timed(handle text, account uuid) returns text language plpgsql as $$ declare t0 timestamptz; t1 timestamptz; t2 timestamptz; begin t0 := clock_timestamp(); perform public.designer_page(handle, false); t1 := clock_timestamp(); perform public.designer_mine(account); t2 := clock_timestamp(); return format('designer_page %s ms, designer_mine %s ms', round(extract(epoch from t1 - t0) * 1000, 1), round(extract(epoch from t2 - t1) * 1000, 1)); end $$;
select coalesce((select p.handle || ', ' || (select count(*) from public.shared_models m where m.owner = p.account and m.published) || ' models: ' || pg_temp.timed(p.handle, p.account) from public.people p where p.account = (select m.owner from public.shared_models m join public.people q on q.account = m.owner where m.published group by m.owner order by count(*) desc limit 1)), 'no designer with a profile has a published model yet') as "the busiest designer with a profile";
select (select count(*) from public.shared_models m where m.owner = b.owner and m.published) as models, pg_temp.timed('', b.owner) as "the owner with the most models, profile or not" from (select owner from public.shared_models where published group by owner order by count(*) desc limit 1) b;
create function pg_temp.tries(statement text) returns text language plpgsql as $$ begin execute statement; return 'allowed'; exception when others then return 'refused: ' || sqlerrm; end $$;
insert into auth.users (id, instance_id, aud, role, email) values ('00000000-0000-4000-8000-0000000000d1', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'designers-ada@resend.dev'), ('00000000-0000-4000-8000-0000000000d2', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'designers-bob@resend.dev'), ('00000000-0000-4000-8000-0000000000d3', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'designers-cy@resend.dev'), ('00000000-0000-4000-8000-0000000000d5', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'designers-ed@resend.dev');
select public.answer_age('00000000-0000-4000-8000-0000000000d1', true)->>'over_13' as ada, public.answer_age('00000000-0000-4000-8000-0000000000d2', true)->>'over_13' as bob, public.answer_age('00000000-0000-4000-8000-0000000000d5', true)->>'over_13' as ed;
insert into public.people (account, handle, name) values ('00000000-0000-4000-8000-0000000000d1', 'designers-try-ada', 'Ada Try'), ('00000000-0000-4000-8000-0000000000d2', 'designers-try-bob', 'Bob Try');
-- Ada's models: a castle listed and credited, a secret by link only, one listed without her name. Bob's two remixes of the castle: one listed, one by link. Her castle was shared 60 days ago.
insert into public.shared_models (id, owner, name, author, parts, bytes, listed, listed_at, test, created_at, published) values ('DesignTr01', '00000000-0000-4000-8000-0000000000d1', 'Try castle', 'Ada Try', 3, 100, true, now() - interval '60 days', true, now() - interval '60 days', true), ('DesignTr02', '00000000-0000-4000-8000-0000000000d1', 'Try secret', 'Ada Try', 3, 100, false, null, true, now() - interval '20 days', true), ('DesignTr03', '00000000-0000-4000-8000-0000000000d1', 'Try nameless', null, 3, 100, true, now() - interval '20 days', true, now() - interval '20 days', true), ('DesignTr04', '00000000-0000-4000-8000-0000000000d2', 'Try castle, taller', 'Bob Try', 4, 120, true, now() - interval '5 days', true, now() - interval '5 days', true), ('DesignTr05', '00000000-0000-4000-8000-0000000000d2', 'Try castle, by link', 'Bob Try', 4, 120, false, null, true, now() - interval '45 days', true);
update public.shared_models set remixed_from = 'DesignTr01' where id in ('DesignTr04', 'DesignTr05');
insert into public.share_versions (model, n, at, parts, bytes) values ('DesignTr01', 1, now() - interval '60 days', 3, 100), ('DesignTr02', 1, now() - interval '20 days', 3, 100), ('DesignTr03', 1, now() - interval '20 days', 3, 100), ('DesignTr04', 1, now() - interval '5 days', 4, 120), ('DesignTr05', 1, now() - interval '45 days', 4, 120);
insert into public.share_tests (model, n, app, file_hash, parts, steps, tests, passed) values ('DesignTr01', 1, '0.3.0', repeat('a', 64), 3, 2, '{"stands": {"ok": true}, "steps": {"ok": true}, "parts": {"ok": true}, "whole": {"ok": true}}', true);
-- Builds finished: three devices on the castle, one of them 40 days ago; one on the secret.
select public.count_build('DesignTr01', repeat('1', 32)) as one, public.count_build('DesignTr01', repeat('2', 32)) as two, public.count_build('DesignTr01', repeat('3', 32)) as three, public.count_build('DesignTr01', repeat('3', 32)) as "the same device again", public.count_build('DesignTr02', repeat('4', 32)) as secret;
update public.model_builds set at = now() - interval '40 days' where model = 'DesignTr01' and device = repeat('3', 32);
-- Opens: count_view answers as it did before the trigger, with it and without it. On the secret, with the trigger off: a visitor counted once, then not; on the nameless one, with it on: the same; a model that is not there, never.
alter table public.model_views disable trigger model_opens_count;
select public.count_view('DesignTr02', repeat('a', 32)) as "without the trigger: first", public.count_view('DesignTr02', repeat('a', 32)) as "again";
select (select views from public.model_stats where model = 'DesignTr02') as views, (select count(*) from public.model_views where model = 'DesignTr02') as visitors, (select count(*) from public.model_opens where model = 'DesignTr02') as "opens rows";
alter table public.model_views enable trigger model_opens_count;
select public.count_view('DesignTr03', repeat('a', 32)) as "with the trigger: first", public.count_view('DesignTr03', repeat('a', 32)) as "again";
select (select views from public.model_stats where model = 'DesignTr03') as views, (select count(*) from public.model_views where model = 'DesignTr03') as visitors, (select opens from public.model_opens where model = 'DesignTr03' and day = current_date) as "opens today";
select public.count_view('NoSuchMode', repeat('b', 32)) as "a model not there", (select count(*) from public.model_opens where model = 'NoSuchMode') as "its opens rows";
-- Three visitors on the castle today, and days kept from before: five 10 days ago, seven 40 days ago.
select public.count_view('DesignTr01', repeat('c', 32)) and public.count_view('DesignTr01', repeat('d', 32)) and public.count_view('DesignTr01', repeat('e', 32)) as "three visitors";
insert into public.model_opens (model, day, opens) values ('DesignTr01', current_date - 10, 5), ('DesignTr01', current_date - 40, 7);
update public.model_stats set views = views + 12 where model = 'DesignTr01';
select day = current_date as today, opens from public.model_opens where model = 'DesignTr01' order by day desc;
-- Comments on the castle: Bob's (counted), Ada's own answer (not), Bob's that Ada hid (not), Ed's removed (not), and Bob's of 40 days ago (counted, not in the last 30).
insert into public.model_comments (model, version, author, body, at) values ('DesignTr01', 1, '00000000-0000-4000-8000-0000000000d2', 'Try: built it with my daughter', now() - interval '2 days'), ('DesignTr01', 1, '00000000-0000-4000-8000-0000000000d1', 'Try: thank you', now() - interval '1 day'), ('DesignTr01', 1, '00000000-0000-4000-8000-0000000000d2', 'Try: hidden by Ada', now() - interval '3 days'), ('DesignTr01', 1, '00000000-0000-4000-8000-0000000000d5', 'Try: removed by Ed', now() - interval '3 days'), ('DesignTr01', 1, '00000000-0000-4000-8000-0000000000d2', 'Try: an old one', now() - interval '40 days');
update public.model_comments set hidden_at = now() where body = 'Try: hidden by Ada';
update public.model_comments set removed_at = now(), removed_by = 'author' where body = 'Try: removed by Ed';
-- Photos of builds of the castle: Bob's and Ed's (shown), Ada's own (not someone else's build), and one of Bob's that Ada hid.
insert into public.build_photos (id, model, account, words, width, height, bytes, was, at) values ('DesignPh01', 'DesignTr01', '00000000-0000-4000-8000-0000000000d2', 'Built the castle', 1600, 1200, 200000, 'jpeg', now() - interval '3 hours'), ('DesignPh02', 'DesignTr01', '00000000-0000-4000-8000-0000000000d5', 'Mine has a moat', 1600, 1200, 200000, 'jpeg', now() - interval '2 hours'), ('DesignPh03', 'DesignTr01', '00000000-0000-4000-8000-0000000000d1', 'My own', 1600, 1200, 200000, 'jpeg', now() - interval '1 hour'), ('DesignPh04', 'DesignTr01', '00000000-0000-4000-8000-0000000000d2', 'Hidden by Ada', 1600, 1200, 200000, 'jpeg', now() - interval '4 hours');
update public.build_photos set hidden_at = now() where id = 'DesignPh04';
-- Her page, as anybody sees it with tests: one model listed and credited, 3 builds, 2 remixes (the listed one and the one by link, as the card counts), 2 comments, 1 Tested, Ed's and Bob's photos (Ed has no profile), and the castle's card's comments.
select d->>'models' as models, d->>'builds' as builds, d->>'remixes' as remixes, d->>'comments' as comments, d->>'tested' as tested, d->>'likes' as likes, d->>'builders' as builders, d->'cards' as cards from (select public.designer_page('designers-try-ada', true) as d) x;
select p->>'id' as photo, p->>'model' as model, p->>'words' as words, p->'by'->>'handle' as by from jsonb_array_elements(public.designer_page('designers-try-ada', true)->'photos') p;
-- Without tests (a visitor): her test models are not counted. A handle nobody has: nothing. Bob's page: his own models' numbers, none of hers.
select public.designer_page('designers-try-ada')->>'models' as "a visitor's count of her test models", public.designer_page('designers-try-nobody', true) is null as "nobody has that handle", public.designer_page('designers-try-bob', true)->>'models' as "Bob's models", public.designer_page('designers-try-bob', true)->>'builds' as "Bob's builds";
-- The same numbers the live queries give: profile_page's models and likes, and the sum of each card directory_models gives for her models.
select (public.profile_page('designers-try-ada', true)->>'models') = (public.designer_page('designers-try-ada', true)->>'models') as "models as profile_page", (public.profile_page('designers-try-ada', true)->>'likes') = (public.designer_page('designers-try-ada', true)->>'likes') as "likes as profile_page", (select sum((c->>'builds')::int) from public.directory_models(jsonb_build_object('owner', '00000000-0000-4000-8000-0000000000d1', 'tests', true, 'size', 49)) c)::text = public.designer_page('designers-try-ada', true)->>'builds' as "builds as the cards", (select sum((c->>'remixes')::int) from public.directory_models(jsonb_build_object('owner', '00000000-0000-4000-8000-0000000000d1', 'tests', true, 'size', 49)) c)::text = public.designer_page('designers-try-ada', true)->>'remixes' as "remixes as the cards", (select count(*) from public.directory_models(jsonb_build_object('owner', '00000000-0000-4000-8000-0000000000d1', 'tests', true, 'size', 49)) c where (c->>'tested')::boolean)::text = public.designer_page('designers-try-ada', true)->>'tested' as "Tested as the cards";
-- The comments it counts are the ones the castle's page shows a visitor, less Ada's own.
select (select count(*) from jsonb_array_elements(public.comments_on('DesignTr01')->'comments') c where not (c->>'by_owner')::boolean)::text = public.designer_page('designers-try-ada', true)->'cards'->'DesignTr01'->>'comments' as "comments as the page shows them";
-- What only Ada sees: her three published models, the castle first (most opens), with the last 30 days and since it was shared.
select m->>'id' as model, m->>'listed' as listed, m->>'credited' as credited, m->>'opens' as opens, m->>'opens_ever' as opens_ever, m->>'builds' as builds, m->>'builds_ever' as builds_ever, m->>'remixes' as remixes, m->>'remixes_ever' as remixes_ever, m->>'comments' as comments, m->>'comments_ever' as comments_ever, m->>'tested' as tested, m->>'photos_count' as photos, m->>'builders' as builders from jsonb_array_elements(public.designer_mine('00000000-0000-4000-8000-0000000000d1')->'models') m;
select p->>'id' as photo, p->>'words' as words, p->'by'->>'name' as by from jsonb_array_elements((select m->'photos' from jsonb_array_elements(public.designer_mine('00000000-0000-4000-8000-0000000000d1')->'models') m where m->>'id' = 'DesignTr01')) p;
select d->>'days' as days, (d->>'since')::date = current_date - 29 as "since 29 days ago", (d->>'counted_from')::date <= current_date - 40 as "counted from the oldest day kept" from (select public.designer_mine('00000000-0000-4000-8000-0000000000d1') as d) x;
-- The last 7 days instead: the castle's opens today only, its one comment of 2 days ago, its remix of 5 days ago.
select m->>'id' as model, m->>'opens' as opens, m->>'builds' as builds, m->>'remixes' as remixes, m->>'comments' as comments from jsonb_array_elements(public.designer_mine('00000000-0000-4000-8000-0000000000d1', 7)->'models') m where m->>'id' = 'DesignTr01';
-- Nobody else's: Bob's answer has only his own two, no account none, and days out of bounds are held to 1 and 90.
select (select string_agg(m->>'id', ', ' order by m->>'id') from jsonb_array_elements(public.designer_mine('00000000-0000-4000-8000-0000000000d2')->'models') m) as "Bob's", public.designer_mine(null) is null as "no account", public.designer_mine('00000000-0000-4000-8000-0000000000d1', 0)->>'days' as "0 days", public.designer_mine('00000000-0000-4000-8000-0000000000d1', 400)->>'days' as "400 days";
-- An account taken out of the gallery: no page, and its comment and photo not counted on hers.
insert into public.barred_accounts (account, reason) values ('00000000-0000-4000-8000-0000000000d2', 'Try');
select public.designer_page('designers-try-bob', true) is null as "Bob taken out: no page", public.designer_page('designers-try-ada', true)->>'comments' as "her comments without his", public.designer_page('designers-try-ada', true)->>'builders' as "her builders without him";
delete from public.barred_accounts where account = '00000000-0000-4000-8000-0000000000d2';
-- Under 13: Cy made a profile saying he was 13 or over, and his answer is under 13 now (set here by hand: answer_age asks again only after a year); no page.
select public.answer_age('00000000-0000-4000-8000-0000000000d3', true)->>'over_13' as cy;
insert into public.people (account, handle, name) values ('00000000-0000-4000-8000-0000000000d3', 'designers-try-cy', 'Cy Try');
select public.designer_page('designers-try-cy', true) is not null as "Cy 13 or over: a page";
update public.profiles set over_13 = false where id = '00000000-0000-4000-8000-0000000000d3';
select public.designer_page('designers-try-cy', true) is null as "Cy under 13: no page";
-- Nobody but the server: no grant on model_opens to any key, the service role's included; row security on; the functions the service role's alone.
select count(*) as "grants on model_opens to anon, authenticated or service_role" from information_schema.role_table_grants where table_schema = 'public' and table_name = 'model_opens' and grantee in ('anon', 'authenticated', 'service_role');
select relname, relrowsecurity from pg_class where relname = 'model_opens' and relkind = 'r';
select p.proname, has_function_privilege('anon', p.oid, 'execute') as anon, has_function_privilege('authenticated', p.oid, 'execute') as authenticated, has_function_privilege('service_role', p.oid, 'execute') as service_role from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname in ('designer_said', 'designer_page', 'designer_mine', 'model_opens_count') order by p.proname;
-- And on a busy designer, made here: 300 models listed, 30 days of opens on each, 3,000 builds, 600 comments and 300 photos by twenty people, and 100 remixes.
insert into auth.users (id, instance_id, aud, role, email) select ('00000000-0000-4000-8000-000000000e' || lpad(n::text, 2, '0'))::uuid, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'designers-many-' || n || '@resend.dev' from generate_series(1, 20) n;
select count(*) as "twenty said 13 or over" from (select public.answer_age(('00000000-0000-4000-8000-000000000e' || lpad(n::text, 2, '0'))::uuid, true) from generate_series(1, 20) n) x;
insert into public.people (account, handle, name) select ('00000000-0000-4000-8000-000000000e' || lpad(n::text, 2, '0'))::uuid, 'designers-many-' || n, 'Many ' || n from generate_series(1, 20) n;
insert into public.shared_models (id, owner, name, author, parts, bytes, listed, listed_at, test, created_at, published) select 'DesBig' || lpad(n::text, 4, '0'), '00000000-0000-4000-8000-0000000000d1', 'Big ' || n, 'Ada Try', 3, 100, true, now() - make_interval(days => n % 50), true, now() - make_interval(days => n % 50 + 1), true from generate_series(1, 300) n;
insert into public.share_versions (model, n, at, parts, bytes) select 'DesBig' || lpad(n::text, 4, '0'), 1, now() - make_interval(days => n % 50 + 1), 3, 100 from generate_series(1, 300) n;
insert into public.model_opens (model, day, opens) select 'DesBig' || lpad(n::text, 4, '0'), current_date - d, 1 + (n * d) % 17 from generate_series(1, 300) n, generate_series(0, 29) d;
insert into public.model_builds (model, device, at) select 'DesBig' || lpad((1 + k % 300)::text, 4, '0'), md5('designers-many-build-' || k), now() - make_interval(hours => k % 1000) from generate_series(1, 3000) k;
insert into public.model_stats (model, builds) select b.model, count(*) from public.model_builds b where b.model like 'DesBig%' group by b.model on conflict (model) do update set builds = excluded.builds;
insert into public.model_comments (model, version, author, body, at) select 'DesBig' || lpad((1 + k % 300)::text, 4, '0'), 1, ('00000000-0000-4000-8000-000000000e' || lpad((1 + k % 20)::text, 2, '0'))::uuid, 'Try: many ' || k, now() - make_interval(hours => k % 700) from generate_series(1, 600) k;
insert into public.build_photos (id, model, account, words, width, height, bytes, was, at) select 'DesBP' || lpad(k::text, 5, '0'), 'DesBig' || lpad((1 + k % 300)::text, 4, '0'), ('00000000-0000-4000-8000-000000000e' || lpad((1 + k % 20)::text, 2, '0'))::uuid, 'Try many ' || k, 1600, 1200, 200000, 'jpeg', now() - make_interval(hours => k % 500) from generate_series(1, 300) k;
insert into public.shared_models (id, owner, name, author, parts, bytes, listed, listed_at, test, created_at, published, remixed_from) select 'DesRmx' || lpad(k::text, 4, '0'), ('00000000-0000-4000-8000-000000000e' || lpad((1 + k % 20)::text, 2, '0'))::uuid, 'Remix ' || k, 'Many', 3, 100, true, now() - make_interval(days => k % 40), true, now() - make_interval(days => k % 40), true, 'DesBig' || lpad((1 + k % 300)::text, 4, '0') from generate_series(1, 100) k;
analyze public.model_opens;
select d->>'models' as models, d->>'builds' as builds, d->>'remixes' as remixes, d->>'comments' as comments, d->>'builders' as builders, jsonb_array_length(d->'photos') as photos from (select public.designer_page('designers-try-ada', true) as d) x;
select jsonb_array_length(d->'models') as models, (select sum((m->>'opens')::int) from jsonb_array_elements(d->'models') m) as opens, (select sum((m->>'builds')::int) from jsonb_array_elements(d->'models') m) as builds, length(d::text) as "bytes of jsonb" from (select public.designer_mine('00000000-0000-4000-8000-0000000000d1') as d) x;
create function pg_temp.best(handle text, account uuid) returns text language plpgsql as $$ declare t0 timestamptz; a numeric := 1e9; b numeric := 1e9; begin for i in 1..3 loop t0 := clock_timestamp(); perform public.designer_page(handle, true); a := least(a, extract(epoch from clock_timestamp() - t0) * 1000); t0 := clock_timestamp(); perform public.designer_mine(account); b := least(b, extract(epoch from clock_timestamp() - t0) * 1000); end loop; return format('designer_page %s ms, designer_mine %s ms (best of three)', round(a, 1), round(b, 1)); end $$;
select pg_temp.best('designers-try-ada', '00000000-0000-4000-8000-0000000000d1') as "Ada with 303 models"
